using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using PhoneStore.Core.Contracts;
internal sealed partial class QaSuite
{
    async Task<int[]> Parallel(params Func<Task<HttpResponseMessage>>[] sends){var start=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var tasks=sends.Select(async f=>{await start.Task;using var r=await f();return(int)r.StatusCode;}).ToArray();start.SetResult();return await Task.WhenAll(tasks);}
    async Task Concurrency(){
        await using(var db=Open()){var secondary=new PhoneStore.Infrastructure.Data.Account{Username="qa-admin2",Role="ADMIN"};secondary.PasswordHash=new Microsoft.AspNetCore.Identity.PasswordHasher<PhoneStore.Infrastructure.Data.Account>().HashPassword(secondary,adminPassword);db.Accounts.Add(secondary);await db.SaveChangesAsync();}
        admin2=new(url,"ADMIN_2",requests);await admin2.Login("qa-admin2",adminPassword,true);
        await Check("SEC-011","Hai khách tranh hàng cuối qua HTTP song song","Đúng1 thành công1 thiếu tồn, DB reserved1",async()=>{var v=await Fixture(1);var ra=await Cart(a,v);var rb=await Cart(b,v);var statuses=await Parallel(()=>a.Send("/api/orders",ra),()=>b.Send("/api/orders",rb));Assert(statuses.Count(x=>x==200)==1&&statuses.Count(x=>x==409)==1);var s=await Stock(v[0].Id);Assert(s.OnHand==1&&s.Reserved==1);});
        await Check("SEC-012","Khách hủy trong lúc Admin xác nhận","Một200/một409; kho phù hợp trạng thái cuối",async()=>{var v=await Fixture(1);var o=await Place(a,await Cart(a,v));var statuses=await Parallel(()=>a.Send($"/api/orders/{o.Id}/cancel",new TransitionRequest(o.Version,Guid.NewGuid(),"QA")),()=>admin.Send($"/api/admin/orders/{o.Id}/confirm",new TransitionRequest(o.Version,Guid.NewGuid())));Assert(statuses.Count(x=>x==200)==1&&statuses.Count(x=>x==409)==1);o=await admin.Read<OrderDto>($"/api/admin/orders/{o.Id}");Assert((await Stock(v[0].Id)).Reserved==(o.Status=="DA_HUY"?0:1));});
        await Check("SEC-013","Hai request chốt cùng phiếu nhập","Một200/một409, kho chỉ tăng2",async()=>{var v=(await Fixture(0))[0];var id=await Create("/api/admin/purchases",new PurchaseInput(supplier,[new(v.Id,2,100m)]));var p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{id}");var statuses=await Parallel(()=>admin.Send($"/api/admin/purchases/{id}/confirm",new TransitionRequest(p.Version,Guid.NewGuid())),()=>admin2.Send($"/api/admin/purchases/{id}/confirm",new TransitionRequest(p.Version,Guid.NewGuid())));Assert(statuses.Count(x=>x==200)==1&&statuses.Count(x=>x==409)==1&&(await Stock(v.Id)).OnHand==2);});
        await Check("SEC-014","Hoàn tất/thu tiền cùng đơn song song","Chỉ1 complete/log/thu, snapshot đúng",async()=>{var v=await Fixture(1);var o=await Place(a,await Cart(a,v));await Move(o.Id,"confirm");o=await Move(o.Id,"dispatch");var statuses=await Parallel(()=>admin.Send($"/api/admin/orders/{o.Id}/complete",new TransitionRequest(o.Version,Guid.NewGuid())),()=>admin2.Send($"/api/admin/orders/{o.Id}/complete",new TransitionRequest(o.Version,Guid.NewGuid())));Assert(statuses.Count(x=>x==200)==1&&statuses.Count(x=>x==409)==1);await using var db=Open();Assert(await db.Histories.CountAsync(x=>x.OrderId==o.Id&&x.To=="HOAN_TAT")==1);Assert((await db.Payments.FindAsync(o.Id))!.Amount==o.Total);});
        await Check("SEC-016","Giá đổi cùng lúc checkout","Đơn chốt giá cũ hoặc bị PRICE_CHANGED; không dùng giá giả",async()=>{var v=await Fixture(1);var req=await Cart(a,v);var p=await ProductFor(v[0].Id);var i=Input(p);var statuses=await Parallel(()=>admin.Send($"/api/admin/products/{p.Id}",i with{Variants=i.Variants.Select(x=>x with{Price=1100000m}).ToList()},HttpMethod.Put),()=>a.Send("/api/orders",req));Assert(statuses[0]==200&&statuses[1] is 200 or 409);await using var db=Open();var o=await db.Orders.Include(x=>x.Lines).SingleOrDefaultAsync(x=>x.RequestKey==req.RequestKey);Assert(o==null?statuses[1]==409:o.Lines.Single().Price==1000000m);Assert((await Stock(v[0].Id)).Reserved==(o==null?0:1));});
        await Check("UC03-013","Lỗi sau khi giữ dòng đầu phải rollback","Không đơn/payment/log dang dở; giữ dòng đầu0",async()=>{var v=await Fixture(1,2);var ra=await Cart(a,v);await Place(b,await Cart(b,[v[1]]));await Status(await a.Send("/api/orders",ra),409);Assert((await Stock(v[0].Id)).Reserved==0);await using var db=Open();Assert(!await db.Orders.AnyAsync(x=>x.RequestKey==ra.RequestKey)&&!await db.Movements.AnyAsync(x=>x.OperationKey==ra.RequestKey));});
        await Check("UC08-008","Chốt nhập lỗi SQL ở dòng2 rollback dòng1","HTTP500 được che, tồn đầu0 và phiếu vẫn NHAP",async()=>{var v=await Fixture(0,2);var id=await Create("/api/admin/purchases",new PurchaseInput(supplier,v.Select(x=>new PurchaseLineInput(x.Id,1,100)).ToList()));var p=await admin.Read<PurchaseDto>($"/api/admin/purchases/{id}");await using(var db=Open())await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE TON_KHO SET OnHand={int.MaxValue} WHERE VariantId={v[1].Id}");try{using var response=await admin.Send($"/api/admin/purchases/{id}/confirm",new TransitionRequest(p.Version,Guid.NewGuid()));Assert((int)response.StatusCode==500);var text=await response.Content.ReadAsStringAsync();Assert(!text.Contains("SqlException")&&!text.Contains("UPDATE TON_KHO"));Assert((await Stock(v[0].Id)).OnHand==0);Assert((await admin.Read<PurchaseDto>($"/api/admin/purchases/{id}")).Status=="NHAP");await using var db=Open();Assert(!await db.Movements.AnyAsync(x=>x.PurchaseId==id));}finally{await using var db=Open();await db.Database.ExecuteSqlInterpolatedAsync($"UPDATE TON_KHO SET OnHand=0 WHERE VariantId={v[1].Id}");}});
        await Check("SEC-015","Timeout thật ở proxy sau server commit và retry","Client timeout; retry cùngkey trả đúng1đơn, giữ1",async()=>{
            var v=await Fixture(2);var req=await Cart(a,v);using var listener=new HttpListener();listener.Prefixes.Add("http://localhost:5197/");listener.Start();var committed=new TaskCompletionSource<long>(TaskCreationOptions.RunContinuationsAsynchronously);
            var forward=Task.Run(async()=>{var ctx=await listener.GetContextAsync().WaitAsync(TimeSpan.FromSeconds(15));try{using var upstream=new HttpClient(new HttpClientHandler{UseProxy=false});using var message=new HttpRequestMessage(HttpMethod.Post,url+"/api/orders"){Content=new StreamContent(ctx.Request.InputStream)};message.Content.Headers.ContentType=new("application/json");message.Headers.TryAddWithoutValidation("Cookie",ctx.Request.Headers["Cookie"]);message.Headers.TryAddWithoutValidation("X-CSRF-TOKEN",ctx.Request.Headers["X-CSRF-TOKEN"]);using var response=await upstream.SendAsync(message);Assert(response.IsSuccessStatusCode,"Proxy upstream did not commit");var data=await response.Content.ReadAsByteArrayAsync();var o=JsonSerializer.Deserialize<OrderDto>(data,json)!;committed.TrySetResult(o.Id);await Task.Delay(1700);ctx.Response.StatusCode=200;try{await ctx.Response.OutputStream.WriteAsync(data);}catch(Exception e) when(e is IOException or HttpListenerException){}try{ctx.Response.Close();}catch(HttpListenerException){} }catch(Exception ex){if(committed.Task.IsCompletedSuccessfully && ex is HttpListenerException or IOException)return;committed.TrySetException(ex);throw;}});
            var token=await a.Read<JsonElement>("/api/security/token");using var client=new HttpClient(new HttpClientHandler{CookieContainer=a.Cookies,UseProxy=false}){Timeout=TimeSpan.FromMilliseconds(1000)};using var message=new HttpRequestMessage(HttpMethod.Post,"http://localhost:5197/api/orders"){Content=JsonContent.Create(req)};message.Headers.Add("X-CSRF-TOKEN",token.GetProperty("token").GetString());bool timedOut=false;try{using var response=await client.SendAsync(message);}catch(TaskCanceledException){timedOut=true;}Assert(timedOut,"Client did not time out");var id=await committed.Task.WaitAsync(TimeSpan.FromSeconds(15));var retried=await Place(a,req);Assert(id==retried.Id&&(await Stock(v[0].Id)).Reserved==1);await forward;listener.Stop();
        });
    }
}




